      "card_ids": ["C74"],
      "claim": "Verapamil absolute oral bioavailability in normal subjects was 22.0%, just above threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "High-dose oral metoclopramide absolute bioavailability was 86.6 ± 4.7% in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C78"],
      "claim": "Diphenhydramine absolute oral bioavailability was 72% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Bumetanide absolute oral bioavailability was 0.74 ± 0.23 in normal subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "Metoprolol systemic availability was 50 ± 11% in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C84"],
      "claim": "Tolfenamic acid absolute bioavailability averaged 60% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C73"],
      "claim": "Verapamil absolute oral bioavailability was 18.0% in healthy volunteers at 80 mg, below the 20% threshold, indicating first-pass liability in a related basic amine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Across ten high-transfer human bioavailability datasets, absolute oral F is consistently ≥20% (mostly 22–100%), with only occasional sub-20% values in specific verapamil studies. The query's lipophilic basic amine profile aligns with these moderate-to-high bioavailability drugs, supporting F ≥20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule.",
    "Verapamil, a structurally related basic amine, shows occasional healthy-volunteer F values of 18–19.4%, creating some threshold uncertainty.",
    "Special-population low values (e.g., indomethacin in premature infants) are not directly transferable to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

